CREATE TABLE public.booking_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL CHECK (length(full_name) BETWEEN 1 AND 100), email text NOT NULL CHECK (length(email) <= 255), phone text CHECK (length(phone) <= 40), program text NOT NULL CHECK (program IN ('discovery','one-on-one')), goals text NOT NULL CHECK (length(goals) BETWEEN 10 AND 3000), availability text NOT NULL CHECK (length(availability) BETWEEN 1 AND 500), created_at timestamptz NOT NULL DEFAULT now(), ip_hash text NOT NULL, email_status text NOT NULL DEFAULT 'pending' CHECK (email_status IN ('pending','accepted','failed')), email_id text); GRANT ALL ON public.booking_requests TO service_role; ALTER TABLE public.booking_requests ENABLE ROW LEVEL SECURITY; CREATE INDEX booking_requests_rate_limit ON public.booking_requests(ip_hash, created_at);